def fc30_new1(S):
    parts = []
    p, c = fwd_pole_cand()
    H = [(ONE, "b1_45")]
    acc = account(c)
    rows, ok = [], acc
    for kind in ("Dec", "Con", "Sel"):
        s, k, dec = provenance_of(c, kind, H)
        for accepts in (True, False):
